const items = $input.all();
const results = [];

for (const item of items) {
  const url = item.json['URL'] || '';

  // Pular linhas sem URL ou já concluídas
  const status = item.json['Status'] || item.json['STATUS'] || '';
  if (!url || status === 'Concluído') continue;

  let slug = url.replace(/\/$/, '').split('/').pop();

  let cidade = '';
  const matchCidade = slug.match(/em-(.+)$/);
  if (matchCidade) {
    cidade = matchCidade[1]
      .split('-')
      .map(p => p.charAt(0).toUpperCase() + p.slice(1))
      .join(' ');
  }

  results.push({
    json: {
      ...item.json,
      slug: slug,
      cidade: cidade,
      promocao: item.json['Promoção (%)'] || item.json['Promocao'] || item.json['PROMOÇÃO'] || '0',
      url_original: url,
      row_number: item.json['row_number'] || items.indexOf(item) + 2
    }
  });
}

return results;

// ============================================
// CONFIGURAÇÃO
const GEMINI_API_KEY = 'SUA_CHAVE_GEMINI_AQUI';
const GEMINI_MODEL = 'gemini-3-pro-preview';
const WP_USER = 'admin';
const WP_APP_PASSWORD = 'SUA_APP_PASSWORD_AQUI';
const WP_URL = 'https://salesesantos.adv.br';
// ============================================

const items = $input.all();
const results = [];

for (const item of items) {
  const posts = item.json;
  const post = Array.isArray(posts) ? posts[0] : posts;

  if (!post || !post.id) {
    results.push({ json: { erro: 'Post não encontrado' } });
    continue;
  }

  const tituloAtual = post.title?.rendered || '';
  const descricaoAtual = post.excerpt?.rendered?.replace(/<[^>]*>/g, '').trim() || '';
  const conteudo = post.content?.rendered?.replace(/<[^>]*>/g, '').substring(0, 500) || '';
  const prevData = $('Extrair Slug e Cidade').first().json;
  const cidade = prevData?.cidade || '';
  const promocao = prevData?.promocao || '0';

  // ---- PASSO 1: Chamar Gemini ----
  const geminiBody = {
    systemInstruction: {
      parts: [{
        text: 'Você é um especialista em marketing jurídico e SEO. Reformule títulos e meta descriptions de artigos de advocacia para incluir promoções vigentes. Regras: 1) Título atrativo e profissional com a promoção. 2) Manter palavra-chave principal (área jurídica + cidade). 3) Meta description entre 140-160 caracteres com call-to-action. 4) Tom profissional. 5) Promoção de forma elegante. Responda SEMPRE em JSON: {"novo_titulo": "...", "nova_descricao": "..."}'
      }]
    },
    contents: [{
      role: 'user',
      parts: [{
        text: 'Reformule o título e descrição deste artigo do escritório Sales e Santos Advogados. Título atual: ' + tituloAtual + '. Descrição atual: ' + descricaoAtual + '. Cidade: ' + cidade + '. Promoção: ' + promocao + '% de desconto. Contexto: ' + conteudo + '. Gere novo título e descrição em JSON.'
      }]
    }],
    generationConfig: {
      temperature: 0.7,
      maxOutputTokens: 500,
      responseMimeType: 'application/json'
    }
  };

  let novoTitulo = '';
  let novaDescricao = '';
  let debugGemini = '';

  try {
    const geminiResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent?key=${GEMINI_API_KEY}`,
      body: geminiBody,
      json: true,
      headers: { 'Content-Type': 'application/json' }
    });

    const resposta = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
    debugGemini = resposta;

    // Tentar parsear JSON da resposta
    let parsed = null;
    try {
      parsed = JSON.parse(resposta);
    } catch (_) {
      const jsonMatch = resposta.match(/\{[\s\S]*\}/);
      if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
    }

    if (parsed) {
      // Aceitar múltiplas chaves possíveis
      novoTitulo = parsed.novo_titulo || parsed.title || parsed.titulo || parsed.new_title || '';
      novaDescricao = parsed.nova_descricao || parsed.description || parsed.descricao || parsed.meta_description || parsed.new_description || '';
    }
  } catch (e) {
    novoTitulo = 'ERRO GEMINI: ' + e.message;
    debugGemini = e.message;
  }

  // ---- PASSO 2: Atualizar WordPress ----
  let wpStatus = 'erro';

  if (novoTitulo && !novoTitulo.startsWith('ERRO')) {
    try {
      const auth = Buffer.from(WP_USER + ':' + WP_APP_PASSWORD).toString('base64');
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${WP_URL}/wp-json/wp/v2/posts/${post.id}`,
        body: {
          title: novoTitulo,
          excerpt: novaDescricao
        },
        json: true,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Basic ' + auth
        }
      });
      wpStatus = 'ok';
    } catch (e) {
      wpStatus = 'ERRO WP: ' + e.message;
    }
  }

  results.push({
    json: {
      post_id: post.id,
      novo_titulo: novoTitulo,
      nova_descricao: novaDescricao,
      titulo_anterior: tituloAtual,
      url_original: prevData?.url_original || '',
      row_number: prevData?.row_number || 0,
      wp_status: wpStatus,
      debug_gemini: debugGemini
    }
  });
}

return results;
